namespace ghidra.app.plugin.core.debug.gui.memview;



using docking.action.builder;
using generic.theme;
using ghidra.app.plugin.core.bento;
using ghidra.app.plugin.core.bento;
using ghidra.framework.plugintool;
using ghidra.util;
using resources;

public class MemviewProvider : BentoProvider {

	private static readonly Icon ICON_SYNC =
		ResourceManager.getScaledIcon(new GIcon("icon.widget.imagepanel.reset"), 12, 12);

	public MemviewProvider(PluginTool tool, BentoServicePlugin plugin) : base(tool, plugin, false)
    {
	}

	/* @Override */
	protected void createActions() {
		base.createActions();

		new ToggleActionBuilder("Toggle Tracking", getOwner()) //
				//.menuPath("&Toggle layout") //
				.toolBarIcon(ICON_SYNC)
				.helpLocation(new HelpLocation(getOwner(), "toggle_tracking")) //
				.onAction(ctx => performToggleTracking(ctx))
				.selected(false)
				.buildAndInstallLocal(this);

	}
}
